def drift_bound(gamma, L, delta, steps=100):
    e = 0.0
    for _ in range(steps):
        e = gamma * L * e + delta      # 误差递归
    return e, delta / (1 - gamma * L) if gamma * L < 1 else None

import torch

def lyapunov_max(deltas):
    # deltas: [T] 相邻轨迹偏差的范数序列
    d = torch.as_tensor(deltas, dtype=torch.float32)
    return torch.log(d[-1] / d[0]) / (len(d) - 1)
